WITH enriched AS (SELECT id, customer_id, account_type, status, LEAD(balance) OVER (PARTITION BY account_type ORDER BY opened_date ASC, id ASC) AS next_balance, ROW_NUMBER() OVER (PARTITION BY account_type ORDER BY opened_date ASC, id ASC) AS row_seq, CUME_DIST() OVER (PARTITION BY account_type ORDER BY balance DESC) AS balance_cume_dist FROM accounts) SELECT CASE WHEN balance_cume_dist >= 0.88 THEN 'PREMIUM' ELSE 'STANDARD' END AS balance_cume_dist_tier, status, APPROX_PERCENTILE(next_balance, ARRAY(0.25, 0.5, 0.75)) AS next_balance_quartiles, AVG(balance_cume_dist) AS avg_balance_cume_dist, COUNT(CASE WHEN status = 'OPEN' THEN 1 END) AS open_count FROM enriched GROUP BY CASE WHEN balance_cume_dist >= 0.88 THEN 'PREMIUM' ELSE 'STANDARD' END, status ORDER BY open_count ASC NULLS FIRST
